{
  "run_list": ["recipe[nginx-multisite]", "recipe[cache]", "recipe[fastapi-tutorial]"],
  "nginx": {
    "sites": {
      "test.cluster.local": {
        "document_root": "/var/www/test.cluster.local",
        "ssl_enabled": true
      },
      "ci.cluster.local": {
        "document_root": "/var/www/ci.cluster.local", 
        "ssl_enabled": true
      },
      "status.cluster.local": {
        "document_root": "/var/www/status.cluster.local",
        "ssl_enabled": true
      }
    },
    "ssl": {
      "certificate_path": "/etc/ssl/certs",
      "private_key_path": "/etc/ssl/private"
    }
  },
  "security": {
    "fail2ban": {
      "enabled": true
    },
    "ufw": {
      "enabled": true
    },
    "ssh": {
      "disable_root": true,
      "password_auth": false
    }
  }
}

default['nginx']['sites'] = {
  'test.cluster.local' => {
    'document_root' => '/opt/server/test',
    'ssl_enabled' => true
  },
  'ci.cluster.local' => {
    'document_root' => '/opt/server/ci',
    'ssl_enabled' => true
  },
  'status.cluster.local' => {
    'document_root' => '/opt/server/status',
    'ssl_enabled' => true
  }
}

default['nginx']['ssl']['certificate_path'] = '/etc/ssl/certs'
default['nginx']['ssl']['private_key_path'] = '/etc/ssl/private'

default['security']['fail2ban']['enabled'] = true
default['security']['ufw']['enabled'] = true
default['security']['ssh']['disable_root'] = true
default['security']['ssh']['password_auth'] = false

server {
    listen 80;
    server_name <%= @server_name %>;

    # Redirect all HTTP to HTTPS
    <% if @ssl_enabled %>
    return 301 https://$server_name$request_uri;
}

server {
    listen 443 ssl http2;
    server_name <%= @server_name %>;

    root <%= @document_root %>;
    index index.html index.htm index.php;

    # SSL Configuration
    ssl_certificate <%= @cert_file %>;
    ssl_certificate_key <%= @key_file %>;

    # SSL Security
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers ECDHE-RSA-AES256-GCM-SHA512:DHE-RSA-AES256-GCM-SHA512:ECDHE-RSA-AES256-GCM-SHA384:DHE-RSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-SHA384;
    ssl_prefer_server_ciphers on;
    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 10m;

    # HSTS
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
    <% else %>
    root <%= @document_root %>;
    index index.html index.htm index.php;
    <% end %>

    # Security Headers
    add_header X-Frame-Options DENY always;
    add_header X-Content-Type-Options nosniff always;
    add_header X-XSS-Protection "1; mode=block" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
    add_header Content-Security-Policy "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'self';" always;

    # Gzip compression
    gzip on;
    gzip_vary on;
    gzip_min_length 1024;
    gzip_types text/plain text/css text/xml text/javascript application/javascript application/xml+rss application/json;

    location / {
        try_files $uri $uri/ =404;
    }

    # Hide .htaccess files
    location ~ /\.ht {
        deny all;
    }

    # Hide sensitive files
    location ~ /\.(git|svn) {
        deny all;
    }

    access_log /var/log/nginx/<%= @server_name %>_access.log;
    error_log /var/log/nginx/<%= @server_name %>_error.log;
}
